<template>
  <CardContent class="!pt-0 grid grid-cols-1 md:grid-cols-2 2xl:grid-cols-3 gap-4">
    <AppSearchInputQuery
      :query="params.search_query || null"
      property-name="search_query"
      placeholder="Search Assignments..."
    />
    <AppMultiComboboxQuery
      v-if="showStatus"
      :value="params.assignment_statuses || null"
      :items="assignmentStatusItems"
      property-name="assignment_statuses"
      null-is-all
      items-plural-name="statuses"
      placeholder="All statuses"
      empty-text="No status options"
    />
    <AppMultiComboboxQuery
      v-if="isCanvasser"
      :value="params.assignment_types || null"
      :items="assignmentTypeSelectItems"
      property-name="assignment_types"
      null-is-all
      items-plural-name="types"
      placeholder="All types"
      empty-text="No type options"
    />
    <AppMultiComboboxQuery
      v-if="isCanvasser"
      :value="params.contract_statuses || null"
      :items="contractStatusItems"
      property-name="contract_statuses"
      null-is-all
      items-plural-name="contract statuses"
      placeholder="All contract statuses"
      empty-text="No contract status options"
    />
    <AppLabeledSelectQuery
      :value="`${params.sort_by}|${params.sort_type}`"
      :items="sortItems"
      property-name="sort_by|sort_type"
      :null-is-all="false"
      placeholder="Sorting"
    />
  </CardContent>
</template>

<script setup lang="ts">
import { assignmentStatusItems } from '~/constants/assignments/assignmentStatusConfig';
import { usersAssignmentsSortBy } from '~/constants/assignments/usersAssignmentSortBy';
import { assignmentTypeSelectItems } from '~/constants/assignments/assignmentTypes';
import { contractStatusItems } from '~/constants/contracts/contractStatusConfig';

interface Props {
  isCanvasser: boolean;
  showStatus: boolean;
  params: UserAssignmentParams;
}

const props = defineProps<Props>();

// Pay-rate sorting only applies to regular canvassers; subcontractor canvassers
// have no pay rate, so drop those options for them.
const sortItems = computed(() =>
  props.isCanvasser
    ? usersAssignmentsSortBy
    : usersAssignmentsSortBy.filter((item) => !item.value?.startsWith('price_per_signature'))
);
</script>
