<template>
  <Card v-if="userDetails">
    <CardHeader>
      <CardTitle>Assign New Project</CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-6">
      <Alert
        v-if="userDetails.status === 'blocked' || (isCanvasserLike && userDetails?.hiring_checks?.do_not_hire === true)"
      >
        <AlertDescription
          v-if="userDetails.status === 'blocked' && isCanvasserLike && userDetails?.hiring_checks?.do_not_hire === true"
          ><b>Blocked</b> users or users with <b>do not hire</b> checkmark cannot be assigned to a
          project.</AlertDescription
        >
        <AlertDescription v-else-if="userDetails.status === 'blocked'"
          ><b>Blocked</b> users cannot be assigned to a project.</AlertDescription
        >
        <AlertDescription v-else-if="isCanvasserLike && userDetails?.hiring_checks?.do_not_hire === true"
          >Users with <b>do not hire</b> checkmark cannot be assigned to a project.</AlertDescription
        >
      </Alert>
      <template v-else>
        <div class="flex flex-col gap-4">
          <ComboboxSelector
            v-model="selectedProjectId"
            :items="projectsList"
            label="Project"
            placeholder="Select Project"
            empty-text="No projects found"
            clearable
            :icon="BriefcaseBusinessIcon"
          />
        </div>

        <div class="flex justify-end gap-2">
          <!-- Position is entered in the confirm dialog, so every role sets it in the same place. -->
          <UserDetailsCreateStaffAssignment
            v-if="assignsWithoutPayRates && selectedProjectDetails"
            :user-details="userDetails"
            :project="selectedProjectDetails"
            :assignments-params="assignmentsParams"
            :last-position="lastPosition"
            @assigned="selectedProjectId = null"
          >
            <Button class="h-10 self-end"> Assign Project </Button>
          </UserDetailsCreateStaffAssignment>
          <Button v-else-if="assignsWithoutPayRates" class="h-10 self-end" disabled> Assign Project </Button>
          <UserDetailsCreateCanvasserAssignment
            v-else-if="selectedProjectDetails && isCanvasserLike"
            :user-details="userDetails"
            :project="selectedProjectDetails"
            :assignments-params="assignmentsParams"
            @assigned="selectedProjectId = null"
          >
            <Button class="h-10 self-end"> Assign Project </Button>
          </UserDetailsCreateCanvasserAssignment>
          <Button v-else class="h-10 self-end" disabled> Assign Project </Button>
        </div>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { SelectorProjectItem, GetUserDetailsResponse } from '~/client';
import { BriefcaseBusinessIcon } from 'lucide-vue-next';

interface Props {
  projects: SelectorProjectItem[];
  userDetails: GetUserDetailsResponse;
  assignmentsParams: UserAssignmentParams;
  /** This user's most recent position on any project; prefills the confirm dialog. */
  lastPosition?: string | null;
}

const props = withDefaults(defineProps<Props>(), { lastPosition: null });
const isCanvasserLike = computed(
  () => props.userDetails.role === 'canvasser' || props.userDetails.role === 'subcontractor_canvasser'
);
// Managers and admins hold no pay rates or assignment type, so they skip the canvasser form and
// confirm through UserDetailsCreateStaffAssignment, which is where their position is entered.
// Admins are assignable so they can appear as HQ on the customer-facing Team tab.
const assignsWithoutPayRates = computed(
  () => props.userDetails.role === 'manager' || props.userDetails.role === 'admin'
);

const projectsList = computed<SelectItem[]>(() =>
  props.projects.map((project) => ({
    name: project.name,
    value: project.id,
  }))
);

const selectedProjectId = ref<string | null>(null);

const selectedProjectDetails = computed<SelectorProjectItem | null>(() => {
  if (!selectedProjectId.value) return null;
  return props.projects.find((project) => project.id === selectedProjectId.value) ?? null;
});

onUnmounted(() => {
  selectedProjectId.value = null;
});
</script>

<style scoped lang="scss"></style>
