import * as z from 'zod';
import { positionSchema } from './utils';

/**
 * Confirm-assignment form for staff (manager / admin). Their link carries no pay rates, assignment
 * type, or app username — the position is the only field, so this schema is deliberately one key.
 */
export const staffAssignmentSchema = z.object({
  position: positionSchema,
});

export type StaffAssignmentFormOutput = z.output<typeof staffAssignmentSchema>;
