<template>
  <div class="grid grid-cols-3 gap-4">
    <UserDetailsAssignments
      class="col-span-3 xl:col-span-2"
      :user-id="userDetails.id"
      :role="userDetails.role"
      :is-loading="isLoading"
      :error="error"
      :items="items"
      :total-count="totalCount"
      :all-count="allCount"
      :assignment-status-count="assignmentStatusCount"
      :params="params"
      :refetch="refetch"
    />
    <UserDetailsCreateAssignment
      class="col-span-3 xl:col-span-1 h-fit"
      :user-details="userDetails"
      :projects="selectorProjects"
      :assignments-params="params"
      :last-position="lastPosition"
    />
  </div>
</template>

<script setup lang="ts">
import UserDetailsCreateAssignment from '~/components/users/details/UserDetailsCreateAssignment.vue';
import {
  getUserProjects,
  getSelectorProjectList,
  type GetUserProjectsResponse,
  type GetSelectorProjectListResponse,
  type AssignmentStatus,
  type ProjectSortBy,
  type SortType,
  type AssignmentType,
  type ContractStatus,
} from '~/client';
import type { GetUserDetailsResponse } from '~/client';

definePageMeta({
  backGroup: 'user-details',
  backLabel: 'user',
});

const props = defineProps<{
  userDetails: NonNullable<GetUserDetailsResponse>;
}>();

const route = useRoute();

const params = computed<UserAssignmentParams>(() => {
  const urlParams = {
    ...parsePagination(route.query, { size: 5 }),
    sort_by: (route.query.sort_by as ProjectSortBy) || 'name',
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
    search_query: (route.query.search_query as string) || undefined,
    assignment_statuses: processArrayQueryParameterFromUrl<AssignmentStatus>(route.query.assignment_statuses),
    assignment_types: processArrayQueryParameterFromUrl<AssignmentType>(route.query.assignment_types),
    contract_statuses: processArrayQueryParameterFromUrl<ContractStatus>(route.query.contract_statuses),
  };

  return Object.fromEntries(
    Object.entries(urlParams).filter(([_, value]) => value !== undefined)
  ) as unknown as UserAssignmentParams;
});

const {
  data: userAssignments,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['user-assignments', props.userDetails.id, params.value],
  query: (): Promise<GetUserProjectsResponse> =>
    getUserProjects({
      composable: '$fetch',
      path: { user_id: props.userDetails.id },
      query: params.value,
    }),
  staleTime: 0,
});

const items = computed(() => userAssignments.value?.items ?? []);
const totalCount = computed(() => userAssignments.value?.total_count ?? 0);
const allCount = computed(() => userAssignments.value?.all_count ?? 0);
const assignmentStatusCount = computed(() => userAssignments.value?.assignment_status_counts ?? {});
// Unfiltered by design (see the list route) — prefills the position field when assigning this user
// somewhere new, so a repeat assignment doesn't have to be retyped.
const lastPosition = computed(() => userAssignments.value?.last_position ?? null);

const { data: selectorProjectsResponse } = useQuery({
  key: () => ['selector-unassigned-projects', props.userDetails.id],
  query: (): Promise<GetSelectorProjectListResponse> =>
    getSelectorProjectList({
      composable: '$fetch',
      query: { not_assigned_user_id: props.userDetails.id, statuses: ['active', 'draft'] },
    }),
});

const selectorProjects = computed(() => selectorProjectsResponse.value?.items ?? []);
</script>
