<template>
  <Dialog v-model:open="isOpen" @update:open="onOpenUpdate">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="gap-6 max-w-xs sm:max-w-md px-0">
      <DialogHeader class="px-6">
        <DialogTitle class="text-start">Confirm assignment</DialogTitle>
        <DialogDescription class="text-start">
          Assign <b>{{ username(userDetails) }}</b> to <b>{{ project.name }}</b> as {{ roleLabel }}.
        </DialogDescription>
      </DialogHeader>

      <form id="assignStaffProject" class="px-6" @submit.prevent="onSubmit">
        <FormItemWrapper label="Position" name="position">
          <template #default="{ slots }">
            <div class="flex flex-col gap-1.5">
              <Input
                id="position"
                type="text"
                maxlength="64"
                placeholder="Position on the customer-facing dashboard"
                data-testid="assignment-position-input"
                v-bind="slots.componentField"
              />
              <p class="text-sm text-muted-foreground">
                Optional. Members with a position appear on the project's public Team tab.
              </p>
            </div>
          </template>
        </FormItemWrapper>
      </form>

      <DialogFooter class="flex flex-row justify-end gap-2 px-6">
        <DialogClose as-child>
          <Button variant="outline" class="h-10 px-4" :disabled="isAssigningUser">Cancel</Button>
        </DialogClose>
        <Button type="submit" form="assignStaffProject" :loading="isAssigningUser"> Confirm Assignment </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import type { GetUserDetailsResponse, SelectorProjectItem } from '~/client';
import { defaultPositionForRole } from '~/constants/assignments/positionDefaults';
import { staffAssignmentSchema } from '~/constants/validationSchemas/staffAssignment';
import { getUserRole } from '~/constants/users/userRoles';

interface Props {
  userDetails: GetUserDetailsResponse;
  project: SelectorProjectItem;
  assignmentsParams: UserAssignmentParams;
  /** This user's most recent position on any project; wins over the role default when set. */
  lastPosition?: string | null;
}

const props = withDefaults(defineProps<Props>(), { lastPosition: null });

const emit = defineEmits<{
  assigned: [];
}>();

const { assignUser, isAssigningUser } = useAssignUserToProject();

const isOpen = ref(false);

const roleLabel = computed(() => getUserRole(props.userDetails.role).name);

const { handleSubmit, setValues, resetForm } = useForm({
  validationSchema: toTypedSchema(staffAssignmentSchema),
});

// Reuse what they were last assigned as, so a repeat assignment isn't retyped; fall back to the
// role default (admins have none, which is why their field opens empty on a first assignment).
function initialPosition(): string {
  return props.lastPosition?.trim() || defaultPositionForRole(props.userDetails.role);
}

const onSubmit = handleSubmit(async (values) => {
  if (isAssigningUser.value) return;
  try {
    await assignUser({
      user_id: props.userDetails.id,
      data: {
        project_id: props.project.id,
        price_per_signature: null,
        price_per_hour: null,
        canvassing_application_user_email: null,
        assignment_type: null,
        increased_price_per_hour: null,
        position: values.position ?? null,
      },
      assignmentsCacheParams: { scope: 'user', params: props.assignmentsParams },
    });
    isOpen.value = false;
    emit('assigned');
  } catch (err: any) {
    console.error(err);
  }
});

function onOpenUpdate(open: boolean) {
  // Re-seed on every open so a cancelled edit doesn't persist into the next attempt.
  if (!open) {
    resetForm();
    return;
  }
  setValues({ position: initialPosition() }, false);
}
</script>
