<template>
  <Dialog v-model:open="isOpen" @update:open="onOpenUpdate">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="gap-6 max-w-xs sm:max-w-sm md:max-w-5xl px-0">
      <DialogHeader class="px-6">
        <DialogTitle class="text-start">Review canvasser profile</DialogTitle>
        <DialogDescription />
      </DialogHeader>
      <form id="assignNewProject" class="px-6" @submit.prevent="onSubmitCanvasser">
        <AssignmentInfoForm
          mode="create"
          :user-id="userDetails.id"
          :user-role="userDetails.role"
          :user-full-name="username(userDetails)"
          :project-id="project.id"
          :project-name="project.name"
          :project-type="project.type"
          :payment="project.payment"
        />
      </form>
      <DialogFooter class="flex flex-row justify-end gap-2 px-6">
        <DialogClose as-child>
          <Button variant="outline" class="h-10 px-4" :disabled="isAssigningUser">Cancel</Button>
        </DialogClose>
        <Button type="submit" form="assignNewProject" :loading="isAssigningUser"> Confirm Assignment </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import type { GetUserDetailsResponse, SelectorProjectItem } from '~/client';

interface Props {
  userDetails: GetUserDetailsResponse;
  project: SelectorProjectItem;
  assignmentsParams: UserAssignmentParams;
}

const props = defineProps<Props>();

const emit = defineEmits<{
  assigned: [];
}>();

const isOpen = ref<boolean>(false);

const isRegularCanvasser = computed(() => props.userDetails.role === 'canvasser');

const { resetForm, applyDefaults, submitAssignment, isAssigningUser } = useCanvasserAssignmentForm({
  projectType: () => props.project.type,
  payment: () => props.project.payment,
  isRegularCanvasser,
  projectId: () => props.project.id,
  userId: () => props.userDetails.id,
  userRole: () => props.userDetails.role,
  assignmentsCacheParams: () => ({ scope: 'user', params: props.assignmentsParams }),
  onAssigned: () => {
    isOpen.value = false;
    emit('assigned');
  },
});

const onSubmitCanvasser = submitAssignment;

function onOpenUpdate(open: boolean) {
  if (!open) {
    resetForm();
    return;
  }
  applyDefaults();
}
</script>

<style scoped lang="scss"></style>
