<template>
  <Card>
    <CardHeader>
      <CardTitle>Project Assignments</CardTitle>
    </CardHeader>
    <CardContent class="p-0 md:p-0">
      <UserDetailsAssignmentFilters :is-canvasser="isCanvasser" :show-status="showStatus" :params="params" />
      <FilterTabsNav v-if="showStatus" :items="statusTabs" show-zero-count stretched />
      <AppLoader v-if="isLoading" variant="table" subject="project assignments" />
      <AppError
        v-else-if="error"
        title="Failed to load user project assignments"
        :error="error"
        variant="table"
        :action="refetch"
        action-text="Retry"
      />
      <template v-else>
        <ResponsiveTable>
          <ResponsiveTableHeader>
            <ResponsiveTableHead class="text-accent-foreground text-xs sm:text-sm leading-6"
              >Project
            </ResponsiveTableHead>
            <ResponsiveTableHead v-if="showStatus" class="text-center w-fit text-nowrap">Status</ResponsiveTableHead>
            <ResponsiveTableHead v-if="isCanvasser" class="text-center text-nowrap">Pay rate</ResponsiveTableHead>
            <ResponsiveTableHead v-if="isCanvasser" class="text-center w-fit text-nowrap"
              >Contract status</ResponsiveTableHead
            >
          </ResponsiveTableHeader>
          <ResponsiveTableBody>
            <ResponsiveTableEmpty
              v-if="(totalCount === 0 || items.length === 0) && !isLoading"
              :colspan="columnCount"
              :cols="4"
              :cols-sm="4"
              cell-class="text-center"
            >
              <AppEmpty subject="project assignments" variant="table" />
            </ResponsiveTableEmpty>
            <ResponsiveTableRow
              v-for="project in items"
              v-else
              :key="project.id"
              :to="{
                name: 'assignments-project_id-user_id',
                params: { project_id: project.id, user_id: userId },
              }"
            >
              <ResponsiveTableCell :cols="4" :cols-sm="4" label="Project">
                <p class="text-base line-clamp-2">{{ project.name }}</p>
              </ResponsiveTableCell>
              <ResponsiveTableCell
                v-if="showStatus"
                :cols="isCanvasser ? 2 : 4"
                :cols-sm="isCanvasser ? 2 : 4"
                label="Status"
              >
                <div v-if="project.assignment_status" class="flex md:justify-center">
                  <Badge :variant="getAssignmentStatus(project.assignment_status).variant">
                    {{ getAssignmentStatus(project.assignment_status).name }}
                  </Badge>
                </div>
                <p v-else class="text-base text-muted-foreground md:text-center">N/A</p>
              </ResponsiveTableCell>
              <ResponsiveTableCell v-if="isCanvasser" :cols="2" :cols-sm="2" label="Pay rate">
                <div class="flex flex-col md:items-center">
                  <p class="text-base font-medium">
                    {{
                      typeof project.price_per_signature === 'number'
                        ? `$${project.price_per_signature}`
                        : typeof project.price_per_hour === 'number'
                          ? `$${project.price_per_hour}`
                          : '-'
                    }}
                    <span v-if="typeof project.increased_price_per_hour === 'number'">
                      /
                      {{ `$${project.increased_price_per_hour}` }}</span
                    >
                  </p>
                  <span v-if="project.assignment_type" class="text-xs text-muted-foreground">{{
                    getAssignmentType(project.assignment_type).shortName
                  }}</span>
                </div>
              </ResponsiveTableCell>
              <ResponsiveTableCell v-if="isCanvasser" :cols="2" :cols-sm="2" label="Contract status">
                <div v-if="project.latest_contract_status" class="flex md:justify-center">
                  <Badge :variant="getContractStatus(project.latest_contract_status).variant">
                    {{ getContractStatus(project.latest_contract_status).name }}
                  </Badge>
                </div>
                <p v-else class="text-base text-muted-foreground md:text-center">N/A</p>
              </ResponsiveTableCell>
            </ResponsiveTableRow>
          </ResponsiveTableBody>
          <ResponsiveTableFooter v-if="totalCount > 0" :colspan="columnCount" :cols="4" :cols-sm="4">
            <AppPagination :page="params.page" :size="params.size" :total="totalCount" label="projects" />
          </ResponsiveTableFooter>
        </ResponsiveTable>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { AssignmentStatus, UserProjectListItem } from '~/client';
import { getAssignmentStatus } from '~/constants/assignments/assignmentStatusConfig';
import { getAssignmentType } from '~/constants/assignments/assignmentTypes';
import { getContractStatus } from '~/constants/contracts/contractStatusConfig';
import { FetchError } from 'ofetch';

interface Props {
  userId: string;
  role: string;
  isLoading: boolean;
  error: FetchError | null | undefined;
  items: UserProjectListItem[];
  totalCount: number;
  allCount: number;
  assignmentStatusCount: Record<string, number>;
  params: UserAssignmentParams;
  refetch: () => void;
}

const props = defineProps<Props>();
const isCanvasser = computed(() => props.role === 'canvasser');
const isSubcontractorCanvasser = computed(() => props.role === 'subcontractor_canvasser');
// Both canvassers and subcontractor canvassers have an assignment status; only
// regular canvassers have pay rate and contract data.
const showStatus = computed(() => isCanvasser.value || isSubcontractorCanvasser.value);
const columnCount = computed<1 | 2 | 4>(() => (isCanvasser.value ? 4 : showStatus.value ? 2 : 1));

const statusTabs = computed<NavigationItem[]>(() =>
  buildMultiSelectStatusTabs<AssignmentStatus>({
    source: filteredAssignmentStatusesForTabs(),
    current: props.params.assignment_statuses ?? [],
    allCount: props.allCount,
    counts: props.assignmentStatusCount,
    buildTo: (next) => ({
      name: 'users-id-assignments',
      params: { id: props.userId },
      query: { ...useRoute().query, page: 1, assignment_statuses: next.length ? next : undefined },
    }),
  })
);
</script>

<style scoped lang="scss"></style>
